function sum(arr) {
    if (!Array.isArray(arr)) {
        throw new Error('Input must be an array');
    }

    if (arr.length === 0) {
        return 0;
    }

    let result = 0;
    for (let i of arr) {
        if (typeof i !== 'number' || isNaN(i)) {
            console.warn(`Skipping non-numeric value: ${i}`);
            continue;
        }
        result += i;
    }
    return result;
}

module.exports = sum;
